<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { currentUser, loadMyRoles } from '../data/user'
import {
	tebusPillClass,
	STATE_ALLOW_EDIT,
	MOTOR_TARIKAN_FILTERS,
	AKSI_WORKFLOW_MAJU,
	angsuranTunggakTidakDibayar,
} from '../data/tebusMotorStatus'
import { notifyError, notifySuccess } from '../composables/toast'
import { openPdf } from '../composables/pdfViewer'
import { useBackNavigation } from '../composables/useBackNavigation'
import SelectMenu from '../components/SelectMenu.vue'

const route = useRoute()
const { backTarget, backLabel } = useBackNavigation(
	{ name: 'TebusMotor' },
	'Tebus Motor Nasabah',
)
const name = computed(() => route.params.name)
const DOCTYPE = 'Tebus Motor Nasabah'

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

const doc = createResource({
	url: 'frappe.client.get',
	makeParams() {
		return { doctype: DOCTYPE, name: name.value }
	},
	auto: false,
})

const banner = ref('')
const metaFields = ref([])
const metaError = ref('')
const form = reactive({})

async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === DOCTYPE) || docs[0]
		metaFields.value = (dt && dt.fields) || []
	} catch (e) {
		metaError.value = e.message || String(e)
	}
}

function isNullVal(v) {
	return v == null || v === ''
}

function evalCondition(expr) {
	if (!expr) return true
	try {
		const code = String(expr).replace(/^eval:/, '')
		const frappeShim = { session: { user: currentUser.user || '' } }
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		// eslint-disable-next-line no-new-func
		return !!new Function(
			'doc',
			'frappe',
			'in_list',
			'cint',
			'cstr',
			'flt',
			`return (${code})`
		)(form, frappeShim, in_list, cint, cstr, flt)
	} catch (e) {
		return true
	}
}

// Section → kolom → field. Meniru form desk: hidden disembunyikan; read_only KOSONG
// disembunyikan (muncul saat terisi, mis. setelah pilih Motor Tarikan); read_only
// ADA isi tampil terkunci; depends_on dihormati.
const sections = computed(() => {
	const secs = []
	let curSection = null
	let curCol = null
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Section Break') {
			curCol = []
			curSection = { label: f.label || '', depends_on: f.depends_on, columns: [curCol] }
			secs.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) {
				curCol = []
				curSection = { label: '', columns: [curCol] }
				secs.push(curSection)
			} else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		if (
			[
				'HTML',
				'Button',
				'Heading',
				'Fold',
				'Image',
				'Barcode',
				'Table',
				'Attach',
				'Attach Image',
			].includes(ft)
		)
			continue
		if (f.hidden) continue
		if (f.read_only && isNullVal(form[f.fieldname])) continue
		if (f.depends_on && !evalCondition(f.depends_on)) continue
		if (!curSection) {
			curCol = []
			curSection = { label: '', columns: [curCol] }
			secs.push(curSection)
		}
		curCol.push(f)
	}
	return secs
		.filter((s) => evalCondition(s.depends_on))
		.map((s) => ({ ...s, columns: s.columns.filter((c) => c.length) }))
		.filter((s) => s.columns.length)
})

// ---- Mode baca/edit (mengikuti Allow Edit workflow per state) ----
const editMode = ref(false)
const canEdit = computed(() => {
	const roles = currentUser.roles || []
	if (currentUser.user === 'Administrator') return true
	const allowed = STATE_ALLOW_EDIT[doc.data?.workflow_state] || []
	return allowed.some((r) => roles.includes(r))
})

function isFieldReadOnly(field) {
	if (!editMode.value) return true
	if (field.read_only) return true
	return field.read_only_depends_on ? evalCondition(field.read_only_depends_on) : false
}

function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text'].includes(ft)
}
function isNumberField(ft) {
	return ['Int', 'Float', 'Percent'].includes(ft)
}
function selectOptions(field) {
	return String(field.options || '')
		.split('\n')
		.map((s) => s.trim())
		.filter(Boolean)
}

// ---- Format ----
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(Number(v))}`
}
function parseCurrency(str) {
	if (str == null) return ''
	const cleaned = String(str)
		.replace(/\./g, '')
		.replace(',', '.')
		.replace(/[^\d.]/g, '')
	if (cleaned === '') return ''
	const n = Number(cleaned)
	return Number.isNaN(n) ? '' : n
}
function onCurrencyBlur(field, e) {
	const n = parseCurrency(e.target.value)
	form[field.fieldname] = n
	e.target.value = currencyDisplay(n)
}
function formatDateDisplay(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}

// ---- Link dropdown + fetch_from ----
const openDropdown = ref('')
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)
let linkSearchTimer = null

function filtersFor(field) {
	if (field.fieldname === 'motor_tarikan') return MOTOR_TARIKAN_FILTERS
	return []
}

function toggleLinkDropdown(field) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	fetchLinkResults(field, '')
}

async function fetchLinkResults(field, query) {
	const dt = field.options
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		const params = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(['name']),
			limit_page_length: '20',
			order_by: 'modified desc',
		})
		const filters = [...filtersFor(field)]
		if (query) filters.push(['name', 'like', `%${query}%`])
		if (filters.length) params.set('filters', JSON.stringify(filters))
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		linkResults.value = (json.message || []).map((r) => String(r.name))
	} catch (e) {
		linkResults.value = []
		notifyError(e, 'Gagal memuat pilihan')
	} finally {
		linkSearchLoading.value = false
	}
}
function onLinkSearch(field) {
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, linkSearch.value.trim()), 300)
}
function selectLink(field, value) {
	form[field.fieldname] = value
	openDropdown.value = ''
	applyFetchFrom(field, value)
}

async function applyFetchFrom(linkField, value) {
	const prefix = `${linkField.fieldname}.`
	const targets = metaFields.value.filter(
		(f) => typeof f.fetch_from === 'string' && f.fetch_from.startsWith(prefix)
	)
	if (!targets.length) return
	if (!value) {
		for (const t of targets) form[t.fieldname] = null
		return
	}
	const sourceFields = targets.map((t) => t.fetch_from.slice(prefix.length))
	try {
		const params = new URLSearchParams({
			doctype: linkField.options,
			filters: JSON.stringify({ name: value }),
			fieldname: JSON.stringify(sourceFields),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		if (!res.ok) return
		const data = (await res.json())?.message || {}
		for (const t of targets) {
			const src = t.fetch_from.slice(prefix.length)
			if (src in data) form[t.fieldname] = data[src]
		}
	} catch (e) {
		/* fallback: server isi saat save */
	}
}

// ---- Save ----
const saving = ref(false)

function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

function syncFormFromDoc() {
	Object.assign(form, doc.data || {})
}

async function saveDocument() {
	saving.value = true
	banner.value = ''
	try {
		const payload = JSON.parse(JSON.stringify(form))
		payload.doctype = DOCTYPE
		payload.name = name.value
		const res = await fetch('/api/method/frappe.client.save', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: payload }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		await doc.fetch()
		syncFormFromDoc()
		editMode.value = false
		loadTransitions()
		notifySuccess('Perubahan berhasil disimpan.')
	} catch (e) {
		banner.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
	} finally {
		saving.value = false
	}
}

// ---- Download PDF (hanya saat workflow_state "Approved") ----
// Desk (tebus_motor_nasabah.js) mengambil PDF bertanda tangan dari Document
// Signing Log lewat get_latest_signed_pdf. Di sini urutannya sama, TAPI dengan
// fallback: belum ada Document Signing Config untuk "Tebus Motor Nasabah"
// (hanya Deviasi yang tersemai di setup_document_signing.py), jadi signed PDF
// selalu kosong dan tombol desk-nya efektif mati. Fallback me-render print
// format langsung supaya tombol ini tetap berguna; begitu signing config
// ditambahkan, versi bertanda tangan otomatis yang dipakai.
const TEBUS_PRINT_FORMAT = 'Memo Tebus Unit QR'
const showPdf = computed(() => (doc.data?.workflow_state || '').trim() === 'Approved')
const loadingPdf = ref(false)

// URL render print format live (endpoint sama dengan desk & Deviasi portal).
function livePdfUrl() {
	return (
		`/api/method/frappe.utils.print_format.download_pdf` +
		`?doctype=${encodeURIComponent(DOCTYPE)}` +
		`&name=${encodeURIComponent(name.value)}` +
		`&format=${encodeURIComponent(TEBUS_PRINT_FORMAT)}` +
		`&no_letterhead=0`
	)
}

// Ditampilkan lewat PdfViewer in-app (PDF.js), bukan window.open seperti desk:
// file signed ada di `/private/files` (butuh cookie session) dan endpoint render
// mengirim Content-Disposition attachment — dua-duanya cuma menghasilkan
// halaman kosong di WebView Android yang tak punya renderer PDF.
async function openSignedPdf() {
	if (loadingPdf.value) return
	loadingPdf.value = true
	try {
		let fileUrl = ''
		try {
			const params = new URLSearchParams({
				reference_doctype: DOCTYPE,
				reference_name: name.value,
			})
			const res = await fetch(
				`/api/method/juragan.juragan.doctype.document_signing_log.document_signing_log.get_latest_signed_pdf?${params.toString()}`,
				{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
			)
			if (res.ok) fileUrl = (await res.json().catch(() => ({})))?.message || ''
		} catch (e) {
			// Signed PDF tak terjangkau → tetap lanjut ke render live di bawah.
		}
		openPdf(fileUrl || livePdfUrl(), `Tebus Motor ${name.value}`)
	} catch (e) {
		notifyError(e, 'Gagal membuka PDF')
	} finally {
		loadingPdf.value = false
	}
}

// ---- Workflow (Tebus Motor) ----
const actionsOpen = ref(false)
const transitions = reactive({ loading: false, items: [], applying: '' })

async function loadTransitions() {
	if (!doc.data) return
	transitions.loading = true
	try {
		const res = await fetch('/api/method/frappe.model.workflow.get_transitions', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data }),
		})
		const json = await res.json()
		const seen = new Set()
		transitions.items = (json.message || []).filter((t) => {
			const key = `${t.action}|${t.next_state}`
			if (seen.has(key)) return false
			seen.add(key)
			return true
		})
	} catch (e) {
		transitions.items = []
	} finally {
		transitions.loading = false
	}
}

// ---- Konfirmasi tunggakan sebagian (mirror before_workflow_action desk) ----
// Server hanya mewajibkan minimal satu angsuran tunggak dipilih. Bila masih ada
// tunggakan yang tidak dibayar, setiap aksi workflow maju harus dikonfirmasi.
const tunggakanDialog = reactive({ open: false, action: '', angsuran: '', total: 0 })

function applyAction(action) {
	const tidakDibayar = AKSI_WORKFLOW_MAJU.includes(action)
		? angsuranTunggakTidakDibayar(doc.data)
		: []
	if (!tidakDibayar.length) return runAction(action)

	actionsOpen.value = false
	tunggakanDialog.action = action
	tunggakanDialog.angsuran = tidakDibayar.map((r) => r.angsuran_ke).join(', ')
	tunggakanDialog.total = tidakDibayar.reduce(
		(sum, r) => sum + (Number(r.sisa_tunggakan_angsuran) || 0),
		0
	)
	tunggakanDialog.open = true
}
function konfirmasiTunggakanYa() {
	const action = tunggakanDialog.action
	tunggakanDialog.open = false
	runAction(action)
}
function konfirmasiTunggakanBatal() {
	tunggakanDialog.open = false
}

async function runAction(action) {
	transitions.applying = action
	banner.value = ''
	try {
		const res = await fetch('/api/method/frappe.model.workflow.apply_workflow', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data, action }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		actionsOpen.value = false
		await doc.fetch()
		syncFormFromDoc()
		loadTransitions()
		notifySuccess(`Aksi "${action}" berhasil diterapkan.`)
	} catch (e) {
		banner.value = e.message || String(e)
		actionsOpen.value = false
		notifyError(e, `Gagal menerapkan aksi "${action}"`)
	} finally {
		transitions.applying = ''
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	loadMyRoles()
	await Promise.all([loadMeta(), doc.fetch()])
	syncFormFromDoc()
	loadTransitions()
})
</script>
